diff --git a/setup/init_integrity.go b/setup/init_integrity.go
index 5c16082..7e5c269 100644
--- a/setup/init_integrity.go
+++ b/setup/init_integrity.go
@@ -10,6 +10,7 @@ import (
 	"syscall"

 	"github.com/KogenAI/kogen-coordinator/project"
+	"github.com/KogenAI/kogen-loop/sys"
 )

 type initIntegrityFile struct {
@@ -20,6 +21,24 @@ type initIntegrityFile struct {
 	dir    bool // a directory that did not exist when the snapshot was taken
 }

+// initRefuseSymlinks refuses a symbolic link at a file init writes, before init writes
+// anything: a write through it would modify a file outside the checkout.
+func initRefuseSymlinks(root string, paths []string) error {
+	for _, p := range paths {
+		info, err := os.Lstat(filepath.Join(root, p))
+		if os.IsNotExist(err) {
+			continue
+		}
+		if err != nil {
+			return err
+		}
+		if info.Mode()&os.ModeSymlink != 0 {
+			return sys.Fail("environment", "symlink_target", p+" is a symbolic link; init does not write through it, so replace it with a regular file or remove it first", 5)
+		}
+	}
+	return nil
+}
+
 func initSnapshot(root string, paths []string) ([]initIntegrityFile, error) {
 	var saved []initIntegrityFile
 	var dirs []initIntegrityFile

